<template><div class="catalog-home min-h-screen bg-slate-50 text-slate-900"><section class="border-b bg-white"><div class="mx-auto flex max-w-7xl items-end justify-between px-4 py-7 sm:py-12"><div><p class="text-sm font-bold uppercase tracking-widest text-teal-700">{{ t('nav.products') }}</p><h1 class="mt-2 text-3xl font-black sm:text-4xl md:text-5xl">{{ t('home.featured.title') }}</h1></div><RouterLink to="/products" class="hidden rounded-lg bg-teal-700 px-5 py-3 text-sm font-bold text-white md:block">{{ t('home.featured.viewAll') }}</RouterLink></div></section><div class="mx-auto grid max-w-7xl gap-5 px-4 py-5 lg:grid-cols-[220px_1fr] lg:gap-8 lg:py-8"><aside class="hidden rounded-xl border bg-white p-5 lg:block"><h2 class="font-bold">{{ t('products.allCategories') }}</h2><nav class="mt-4 space-y-2"><RouterLink to="/products" class="block border-l-2 border-teal-600 px-3 py-2 text-sm font-medium">{{ t('products.allCategories') }}</RouterLink></nav></aside><main><div class="mb-5 flex items-center justify-between"><span class="text-sm text-slate-500">{{ products.length }} {{ t('nav.products') }}</span><RouterLink to="/products" class="text-sm font-bold text-teal-700">{{ t('home.featured.viewAll') }}</RouterLink></div><TemplateProductCollection :products="products" :mode="templateMode" grid-class="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3" @click="go" @quick-buy="quickBuy" /></main></div><ProductQuickBuy v-if="selected" :product="selected" :visible="quickVisible" @update:visible="quickVisible = $event" /></div></template>
<script setup lang="ts">import { computed, onMounted, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { useRouter } from 'vue-router'; import { productAPI } from '../../api'; import { useAppStore } from '../../stores/app'; import TemplateProductCollection from '../components/TemplateProductCollection.vue'; import ProductQuickBuy from '../../components/ProductQuickBuy.vue'; const {t}=useI18n(); const router=useRouter(); const app=useAppStore(); const products=ref<any[]>([]); const selected=ref<any>(null); const quickVisible=ref(false); const templateMode=computed<'card'|'list'>(()=>app.config?.template_mode==='list'?'list':'card'); const go=(s:string)=>router.push(`/products/${s}`); const quickBuy=(p:any)=>{selected.value=p;quickVisible.value=true}; onMounted(async()=>{await app.loadConfig();const r=await productAPI.list({page:1,page_size:24});products.value=r.data.data||[]})</script>
